from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class TnltemplateParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_parameter('userLabel', 'TRUE')
        self.set_tnlDN()
        self.set_templateType()

    def set_tnlDN(self):
        val = "MRBTS-{}/TNLSVC-1/TNL-{}".format(self.enb_ent_config['id'], self.mo_num)
        self.set_parameter('tnlDN', val)

    def set_templateType(self):
        if self.mo_num == '1':
            self.set_parameter('templateType', 'OAM')
        elif self.mo_num == '2':
            self.set_parameter('templateType', 'ControlPlane')
        elif self.mo_num == '3':
            self.set_parameter('templateType', 'UserPlane')
